import { test, expect } from '@playwright/test';

test.describe('Search bar expand on focus - Mobile', () => {
  test.beforeEach(async ({ page }) => {
    // Set mobile viewport
    await page.setViewportSize({ width: 375, height: 667 });
    await page.goto('/');
  });

  test('should expand search bar when focused on mobile', async ({ page }) => {
    // Get the search bar input element
    const searchInput = page.getByRole('searchbox');

    // Get the search bar container to check its width
    const searchContainer = page.locator('[data-testid="search-container"]');

    // Get initial width before focus
    const initialWidth = await searchContainer.evaluate(el => el.offsetWidth);

    // Focus on the search input
    await searchInput.focus();

    // Wait for expansion animation to complete
    await page.waitForTimeout(300);

    // Get expanded width after focus
    const expandedWidth = await searchContainer.evaluate(el => el.offsetWidth);

    // Assert that the search bar has expanded
    expect(expandedWidth).toBeGreaterThan(initialWidth);
  });

  test('should collapse search bar when focus is lost on mobile', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');
    const searchContainer = page.locator('[data-testid="search-container"]');

    // Focus on the search input to expand it
    await searchInput.focus();
    await page.waitForTimeout(300);

    const expandedWidth = await searchContainer.evaluate(el => el.offsetWidth);

    // Click outside to lose focus
    await page.click('body', { position: { x: 50, y: 50 } });
    await page.waitForTimeout(300);

    // Get collapsed width
    const collapsedWidth = await searchContainer.evaluate(el => el.offsetWidth);

    // Assert that the search bar has collapsed
    expect(collapsedWidth).toBeLessThan(expandedWidth);
  });

  test('should show search suggestions when expanded and typing on mobile', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');

    // Focus on the search input
    await searchInput.focus();
    await page.waitForTimeout(300);

    // Type in the search box
    await searchInput.fill('test');

    // Wait for suggestions to appear
    await page.waitForTimeout(500);

    // Check that suggestions are visible
    const suggestions = page.getByRole('listbox');
    await expect(suggestions).toBeVisible();
  });

  test('should maintain expanded state while typing on mobile', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');
    const searchContainer = page.locator('[data-testid="search-container"]');

    // Focus and get expanded width
    await searchInput.focus();
    await page.waitForTimeout(300);
    const expandedWidth = await searchContainer.evaluate(el => el.offsetWidth);

    // Type in the search box
    await searchInput.fill('search query');
    await page.waitForTimeout(200);

    // Check width remains expanded
    const widthWhileTyping = await searchContainer.evaluate(el => el.offsetWidth);
    expect(widthWhileTyping).toBe(expandedWidth);
  });

  test('should handle rapid focus and blur on mobile', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');
    const searchContainer = page.locator('[data-testid="search-container"]');

    // Perform rapid focus/blur cycles
    for (let i = 0; i < 3; i++) {
      await searchInput.focus();
      await page.waitForTimeout(100);
      await page.click('body', { position: { x: 50, y: 50 } });
      await page.waitForTimeout(100);
    }

    // Final focus
    await searchInput.focus();
    await page.waitForTimeout(300);

    // Verify search bar is expanded
    const finalWidth = await searchContainer.evaluate(el => el.offsetWidth);
    const initialWidth = await searchContainer.evaluate(el => {
      el.blur();
      return el.offsetWidth;
    });

    expect(finalWidth).toBeGreaterThan(initialWidth);
  });

  test('should display clear button when search bar is expanded with text on mobile', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');

    // Focus on the search input
    await searchInput.focus();
    await page.waitForTimeout(300);

    // Type in the search box
    await searchInput.fill('test query');

    // Check that clear button is visible
    const clearButton = page.getByRole('button', { name: /clear/i });
    await expect(clearButton).toBeVisible();
  });

  test('should clear search text when clear button is clicked on mobile', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');

    // Focus and type
    await searchInput.focus();
    await page.waitForTimeout(300);
    await searchInput.fill('test query');

    // Click clear button
    const clearButton = page.getByRole('button', { name: /clear/i });
    await clearButton.click();

    // Verify input is cleared
    await expect(searchInput).toHaveValue('');
  });

  test('should handle keyboard navigation in expanded search bar on mobile', async ({ page }) => {
    const searchInput = page.getByRole('searchbox');

    // Focus on the search input
    await searchInput.focus();
    await page.waitForTimeout(300);

    // Type to trigger suggestions
    await searchInput.fill('test');
    await page.waitForTimeout(500);

    // Navigate with arrow keys
    await searchInput.press('ArrowDown');

    // Check that first suggestion is highlighted
    const firstSuggestion = page.getByRole('option').first();
    await expect(firstSuggestion).toBeFocused();
  });
});
